// One-bit 2-to-1 multiplexer. Selects between two inputs based on a
// select bit.
module Mux2to1_1bit (
  input  [1:0] A,
  input  [1:0] B,
  input        S,
  output reg   z
);
  always @(*) begin
    case (S)
      1'b0: z = A[0];
      1'b1: z = B[0];
    endcase
  end
endmodule

